/* Token Launch Radar: a dark console theme. One accent (phosphor green), one warning amber,
   hairline borders, tabular numerals; everything else is spacing and a small type scale. */
:root {
  --canvas: #090d11;
  --surface: #10161d;
  --raised: #151e27;
  --ink: #e6efe9;
  --muted: #8b9d93;
  --faint: #5d6f66;
  --border: #20302a;
  --accent: #3ddc97;
  --accent-dim: #1d5c40;
  --amber: #e8b34b;
  --negative: #e0655a;
  --radius-control: 8px;
  --radius-panel: 12px;
  --font-body: system-ui, -apple-system, "Segoe UI", sans-serif;
  --font-num: ui-monospace, "SF Mono", Menlo, Consolas, monospace;
  --s1: 4px; --s2: 8px; --s3: 12px; --s4: 16px; --s5: 24px; --s6: 32px; --s7: 48px;
}

* { box-sizing: border-box; }
html { color-scheme: dark; }
body {
  margin: 0;
  background: var(--canvas);
  color: var(--ink);
  font: 400 15px/1.5 var(--font-body);
  text-wrap: pretty;
}
h1, h2, h3 { margin: 0; letter-spacing: -0.015em; text-wrap: balance; }
h1 { font-size: 29px; line-height: 1.15; font-weight: 650; }
h2 { font-size: 19px; line-height: 1.2; font-weight: 650; }
h3 { font-size: 15px; line-height: 1.25; font-weight: 650; }
p { margin: 0; }
button, input, select { font: inherit; color: inherit; }
button { cursor: pointer; }
.skip {
  position: absolute; left: -9999px; top: 0; padding: var(--s2) var(--s4);
  background: var(--raised); border: 1px solid var(--border); z-index: 30; color: var(--ink);
}
.skip:focus { left: var(--s4); top: var(--s4); }
:focus-visible { outline: 2px solid var(--accent); outline-offset: 2px; }

.shell { max-width: 1340px; margin: 0 auto; padding: var(--s5) var(--s6) var(--s7); }
.top {
  display: flex; align-items: center; justify-content: space-between; gap: var(--s5);
  padding-bottom: var(--s4); border-bottom: 1px solid var(--border);
}
.brand { display: flex; align-items: center; gap: var(--s3); }
.mark {
  width: 26px; height: 26px; border-radius: 50%; flex: none;
  border: 2px solid var(--accent-dim);
  background: radial-gradient(circle at 50% 50%, var(--accent) 0 3px, transparent 4px),
    conic-gradient(from 20deg, rgba(61, 220, 151, 0.35), transparent 90deg, transparent);
}
.brand-name { font-family: var(--font-num); font-size: 14px; letter-spacing: 0.06em; text-transform: uppercase; }
.top-meta { display: flex; flex-wrap: wrap; gap: var(--s3); justify-content: flex-end; color: var(--muted); font-size: 13px; }
.top-meta span { white-space: nowrap; }
.top-meta b { color: var(--ink); font-weight: 500; }

.lede { display: grid; grid-template-columns: minmax(0, 1.4fr) minmax(290px, 0.6fr); gap: var(--s6); padding: var(--s6) 0 var(--s5); }
.lede p { color: var(--muted); max-width: 64ch; margin-top: var(--s2); }
.lede p b { color: var(--ink); font-weight: 550; }
.facts { display: grid; gap: var(--s2); align-content: start; border-left: 1px solid var(--border); padding-left: var(--s5); }
.fact { display: flex; align-items: baseline; justify-content: space-between; gap: var(--s3); }
.fact b { font-family: var(--font-num); font-size: 15px; font-weight: 500; color: var(--accent); }
.fact span { color: var(--muted); font-size: 13px; }

.controls {
  display: flex; flex-wrap: wrap; align-items: end; gap: var(--s3);
  padding: var(--s4) 0; border-top: 1px solid var(--border);
}
.field { display: grid; gap: var(--s1); }
.field label, .field .sub { color: var(--muted); font-size: 12px; }
.field input, .field select {
  min-height: 36px; padding: 0 var(--s3); border: 1px solid var(--border); border-radius: var(--radius-control);
  background: var(--surface); min-width: 170px; color: var(--ink);
}
.field input { min-width: 250px; }
.check { display: flex; align-items: center; gap: var(--s2); min-height: 36px; color: var(--muted); font-size: 13px; }
.check input { width: 16px; height: 16px; accent-color: var(--accent); }
.tabs { display: flex; gap: var(--s1); padding: 3px; border: 1px solid var(--border); border-radius: var(--radius-control); background: var(--surface); }
.tabs button { min-height: 30px; padding: 0 var(--s3); border: 0; border-radius: 6px; background: transparent; color: var(--muted); }
.tabs button[aria-pressed="true"] { background: var(--accent); color: #06110c; font-weight: 600; }
.count { margin-left: auto; color: var(--muted); font-size: 13px; align-self: center; font-family: var(--font-num); }

.panel { background: var(--surface); border: 1px solid var(--border); border-radius: var(--radius-panel); overflow: hidden; }
.table-wrap { overflow-x: auto; }
table { width: 100%; border-collapse: collapse; font-size: 14px; }
caption { text-align: left; padding: var(--s3) var(--s3) 0; }
th, td { padding: 10px var(--s3); border-bottom: 1px solid var(--border); text-align: left; vertical-align: middle; }
thead th { color: var(--muted); font-size: 12px; font-weight: 500; white-space: nowrap; background: var(--surface); }
th button { display: inline-flex; align-items: center; gap: var(--s1); border: 0; background: none; padding: 0; color: inherit; font: inherit; }
th button:hover { color: var(--ink); }
tbody tr { cursor: pointer; }
tbody tr:hover { background: var(--raised); }
tbody tr[data-selected="true"] { background: rgba(61, 220, 151, 0.08); }
tbody tr:last-child td { border-bottom: 0; }
.num { font-family: var(--font-num); font-variant-numeric: tabular-nums; white-space: nowrap; }
.name { display: grid; gap: 1px; }
.name b { font-weight: 600; }
.sub { color: var(--muted); font-size: 12px; }
.pos { color: var(--accent); }
.neg { color: var(--negative); }
.bar { width: 110px; height: 6px; border-radius: 3px; background: #1c2a23; overflow: hidden; flex: none; }
.bar i { display: block; height: 100%; background: var(--accent); }
.implied { display: flex; align-items: center; gap: var(--s2); }
.range { color: var(--faint); font-size: 12px; }
.tag {
  display: inline-block; padding: 1px 7px; border: 1px solid var(--accent-dim); border-radius: 99px;
  color: var(--accent); font-size: 11px; font-family: var(--font-num); white-space: nowrap;
}
.tag.early { border-color: var(--border); color: var(--muted); }
.status { color: var(--muted); font-size: 12px; white-space: nowrap; }

.method { margin-top: var(--s4); padding: var(--s5); display: grid; gap: var(--s3); }
.method p { color: var(--muted); max-width: 78ch; }
.method p b, .method li b { color: var(--ink); font-weight: 550; }
.formula {
  font-family: var(--font-num); font-size: 13px; line-height: 1.8; color: var(--ink);
  background: var(--canvas); border: 1px solid var(--border); border-radius: var(--radius-control); padding: var(--s3) var(--s4);
  overflow-wrap: anywhere;
}
.method ul { margin: 0; padding-left: var(--s5); display: grid; gap: var(--s2); color: var(--muted); }
.peer-table { font-size: 13px; }
.peer-table td, .peer-table th { padding: 6px var(--s3); }
details.peers summary { cursor: pointer; color: var(--accent); font-size: 13px; }

.empty { padding: var(--s7) var(--s5); text-align: center; display: grid; gap: var(--s3); justify-items: center; }
.empty p { color: var(--muted); }
.button { min-height: 36px; padding: 0 var(--s4); border: 1px solid var(--border); border-radius: var(--radius-control); background: var(--raised); color: var(--ink); }
.button.primary { background: var(--accent); border-color: var(--accent); color: #06110c; font-weight: 600; }

.detail {
  position: fixed; top: 0; right: 0; bottom: 0; width: min(540px, 94vw); z-index: 20;
  background: var(--surface); border: 0; border-left: 1px solid var(--border); padding: var(--s5);
  overflow-y: auto; margin: 0 0 0 auto; max-height: 100%; color: var(--ink);
}
.detail::backdrop { background: rgba(3, 6, 5, 0.55); }
.detail-head { display: flex; align-items: start; justify-content: space-between; gap: var(--s4); }
.detail-head > div { min-width: 0; }
.detail-head .sub { overflow-wrap: anywhere; }
.close { flex: none; min-height: 32px; padding: 0 var(--s3); border: 1px solid var(--border); border-radius: var(--radius-control); background: var(--raised); color: var(--ink); }
.detail h2 { margin-top: var(--s1); }
.detail .sub { margin-top: var(--s1); }
.detail-section { margin-top: var(--s5); padding-top: var(--s4); border-top: 1px solid var(--border); }
.detail-section h3 { margin-bottom: var(--s2); }
.equation { display: grid; gap: var(--s2); font-family: var(--font-num); font-size: 13px; }
.equation div { display: flex; justify-content: space-between; gap: var(--s3); }
.equation span { color: var(--muted); font-family: var(--font-body); }
.equation .total { border-top: 1px solid var(--border); padding-top: var(--s2); }
.equation .total b { color: var(--accent); }
.note { color: var(--muted); font-size: 13px; margin-top: var(--s3); }
.note b { color: var(--amber); font-weight: 550; }
.steps { margin: 0; padding-left: var(--s5); display: grid; gap: var(--s3); }
.steps li { padding-left: var(--s1); }
.steps b { display: block; font-weight: 500; }
.cost { color: var(--muted); font-size: 12px; font-family: var(--font-num); }

@media (max-width: 900px) {
  .shell { padding: var(--s4); }
  .lede { grid-template-columns: 1fr; gap: var(--s4); }
  .facts { border-left: 0; border-top: 1px solid var(--border); padding-left: 0; padding-top: var(--s4); }
  .field input { min-width: 0; width: 100%; }
  .bar { width: 64px; }
}
@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after { transition-duration: 0.01ms !important; animation-duration: 0.01ms !important; animation-iteration-count: 1 !important; }
}
